}

.tile-wide {
    width: 250px;
    height: 125px;
    -webkit-column-break-inside: avoid;
    break-inside: avoid;
    display: inline-block;
    background-color: blue;
}

.tile-small {
    width: 125px;
    height: 125px;
    -webkit-column-break-inside: avoid;
    break-inside: avoid;
    display: inline-block;
    background-color: red;
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;div class="tile-container"&gt;
       &lt;div class="tile-large"&gt;1&lt;/div&gt;&lt;div class="tile-wide"&gt;2&lt;/div&gt;&lt;div class="tile-small"&gt;3&lt;/div&gt;&lt;div class="tile-small"&gt;4&lt;/div&gt;&lt;div class="tile-small"&gt;5&lt;/div&gt;&lt;div class="tile-small"&gt;6&lt;/div&gt;&lt;div class="tile-wide"&gt;7&lt;/div&gt;&lt;div class="tile-large"&gt;8&lt;/div&gt;
&lt;/div&gt;</code></pre>
</div>
</div>
</p>
